"""Self-contained local reader for frozen descriptive output. No model execution."""
import json
from common import ROOT,read

def main():
    target=ROOT/'report';target.mkdir(exist_ok=False)
    payload=dict(data=read(ROOT/'analysis/viewer-data.json'),windows=read(ROOT/'figures/real-manifest.json')['plots'],
        stats=read(ROOT/'analysis/window-statistics.json'),synthetic=read(ROOT/'figures/synthetic-manifest.json')['plots'])
    html=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>PVS-B3 · 趋势状态与策略分层</title><style>
:root{--ink:#233e4b;--muted:#63747d;--line:#dce2df;--paper:#f6f5ef}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.65 system-ui,-apple-system,sans-serif}main{max-width:1420px;margin:auto;padding:38px 30px}h1{font-size:32px;line-height:1.25;margin:12px 0}h2{font-size:22px;margin:30px 0 14px}h3{font-size:17px}.kicker{color:#7c6540;font-size:12px;letter-spacing:2px}.lead{max-width:1040px;font-size:17px}.muted,small{color:var(--muted)}.panel{background:white;border:1px solid var(--line);border-radius:15px;padding:23px;margin:20px 0}.five{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.tag{border-top:5px solid var(--c);padding:14px;background:#fff;border-radius:8px}.tag b{font-size:20px}.tag p{font-size:13px;margin-bottom:0}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:16px 0}select,input,button{font:inherit;color:var(--ink);border:1px solid #bbc9cc;background:white;border-radius:7px;padding:8px 11px}button{cursor:pointer}button:hover{background:#edf2ef}select{max-width:560px}.cases{display:flex;gap:8px;flex-wrap:wrap}.cases button{font-size:13px}#slider{width:100%;padding:0}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card{padding:14px;border:1px solid var(--line);border-radius:10px}.value{font-size:26px;font-weight:650;line-height:1.3;margin-top:7px}.sub{font-size:12px;color:var(--muted)}.status{padding:12px 15px;border-left:5px solid #7b9da8;background:#f3f6f5;margin:14px 0}img.plot{display:block;width:100%;height:auto;margin-top:15px;border:1px solid var(--line)}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;padding:10px;border-bottom:1px solid var(--line);vertical-align:top}th{background:#f0f3ef}code{background:#f1f2ec;padding:2px 4px;border-radius:3px}a{color:#236b8a}.scroll{overflow:auto}summary{cursor:pointer;font-weight:600;padding:6px 0}.note{border-left:4px solid #bd8a46;padding:10px 15px;background:#fbf5e9}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:20px}footer{font-size:12px;color:var(--muted);margin:32px 0}@media(max-width:800px){main{padding:20px 12px}.five,.cards{grid-template-columns:1fr 1fr}.twocol{grid-template-columns:1fr}h1{font-size:27px}select{max-width:100%}}
</style><main><div class="kicker">PVS-B3 · LOCAL RESEARCH · 2026-10-25</div>
<h1>先描述趋势，再选择怎样交易</h1><p class="lead">这一版把温度定义为<strong>当前上行证据的完整程度</strong>：月尺度看当前推进，季尺度看背景，急性下跌能直接打断原状态。E0 保留；七个原标的、二十二个固定窗口；没有开仓、卖出或账户回测。</p>
<p class="note">这是一个明确尺度的探索模型，不是唯一客观真值。温度有逻辑顺序，但不是等距收益、上涨概率或跨股票排名；策略阈值变化也不保证收益单调。</p>
<div class="five">
<div class="tag" style="--c:#37579e"><b>freeze</b><br>急性破坏<p>实际负位移形成当前尺度内的量价冲击，优先于旧上行。</p></div>
<div class="tag" style="--c:#72a7bd"><b>cold</b><br>下行证据<p>当前月尺度确认下降，或下降背景尚无局部恢复。</p></div>
<div class="tag" style="--c:#ddd9cf"><b>neutral</b><br>中性 / 恢复中<p>没有明确推进，或下降背景中出现局部反弹。</p></div>
<div class="tag" style="--c:#e5b367"><b>warm</b><br>建立 / 上行整理<p>局部上行正在建立，或上行背景下当前推进暂缓。</p></div>
<div class="tag" style="--c:#cb6147"><b>hot</b><br>双尺度上行<p>月和季尺度均有向上证据，且没有活跃急性破坏。</p></div></div>
<section class="panel"><h2 style="margin-top:0">先看同一批图</h2>
<div class="cases"><button data-case="au_user_consolidation|2025-07-31">黄金整理</button><button data-case="au_2025_26|2026-02-02">黄金急跌</button><button data-case="au_user_decline|2026-04-01">下跌中的反弹</button><button data-case="semi_2026|2026-08-10">半导体反弹</button><button data-case="semi_2022|2022-08-05">2022反弹反例</button><button data-case="688981_SH_2024_26|2024-10-08">中芯快速启动</button><button data-case="001309_SZ_2024_26|2026-07-15">德明利转弱</button></div>
<div class="toolbar"><label>固定窗口 <select id="window"></select></label><label>观察日期 <input id="date" type="date"></label><span id="dateText" class="muted"></span></div>
<input id="slider" type="range"><div id="cards" class="cards"></div><div id="reason" class="status"></div>
<details><summary>这一天的量价与旧算法数据</summary><div id="details" class="scroll"></div></details>
<img id="plot" class="plot" alt="七资产之一的固定窗口，E0和B1/B2/B3并列">
<p class="sub">日期控件切换逐日读数；下方图片始终显示所选完整窗口。橙色底纹是 E0 结构有效，不是账户持仓；蓝点仅标记 freeze，没有卖单。</p></section>
<section class="panel"><h2 style="margin-top:0">黄金两段的实际状态分布</h2><div id="goldStats" class="scroll"></div><p class="sub">日数是状态观察数，不是交易数或胜率。5 月初本身有急跌，不能将整段都当成无波动盘整。完整逐窗数据和失败见下方研究结论。</p></section>
<section class="panel"><h2 style="margin-top:0">变化来自什么</h2><div class="twocol"><div><h3>正常状态：同一个推进公式，两种尺度</h3><p>对已知的 22 / 64 个对数收盘拟合斜率，除以过去 63 个收益的 RMS；得到月 / 季尺度推进。达到 ±1 才建立方向，回到 ±0.5 才释放，避免边缘小摆动反复升级。</p><p>月尺度下降优先成为 cold。月尺度上升、季尺度下降，标记为 neutral / 反弹。两者上升才成为 hot。五档不含任何仓位含义。</p></div><div><h3>急性破坏：当天更新，历史不无限占位</h3><p>原始冲击 q = 日对数变化 / 滞后 RMS。参与调整 q_eff = q × √clip(相对量,1,4)。q_eff ≤ −2 创建独立 freeze 事件；低量不减免真实下跌。</p><p>每条事件分别在实际收复、月尺度下降接管，或离开 21 观察尺度后退出。后两者不称修复。新冲击不会降低旧事件恢复锚，也不会给旧事件续期。</p></div></div>
<p class="note">高量会让部分普通回撤更早触发 freeze；微小但稳定的慢涨也可能 hot；急跌抬高 RMS 会让后续弱阴跌难以达到方向门槛；双尺度确认会延迟 V 形反转。图检会保留这些代价，不用未来标签把它们改对。</p></section>
<section class="panel"><h2 style="margin-top:0">合成路径：先验证语义，再看真实历史</h2><label>固定反事实 <select id="synthetic"></select></label><img id="synthPlot" class="plot" alt="固定合成反事实图"><p class="sub">保留全部 17 条 B2 旧路径，加 7 条事前定义路径；只检查描述与因果性，不计算收益。完整行为结果见 <a href="../validation/behavior.json">behavior.json</a>。</p></section>
<section class="panel"><h2 style="margin-top:0">完整说明与证据</h2><p><a href="../CONCLUSION.md">结论与反例</a> · <a href="../PROTOCOL.md">公式 / 状态转移</a> · <a href="../analysis/selected-facts.csv">固定日期对照表</a> · <a href="../analysis/window-statistics.csv">22 窗统计</a> · <a href="../reviews/raw/RAW_REVIEW.md">原始量价复查</a> · <a href="../reviews/raw/OUTPUT_REVIEW.md">真实图复评</a> · <a href="../validation/checks.json">技术检查</a> · <a href="../complete.json">完成收据</a></p><p>逐日数据：<span id="downloads"></span></p><p class="sub">代码与协议冻结后不按真实结果改门槛。已有历史仍是开发样本；没有未见数据胜率、没有账户晋升、没有自动实盘。</p></section>
<footer>本地研究页面，静态资源，无外部脚本与网络行情。沪金连续拼接规则未独立认证，股票/ETF为原因果研究坐标；源截止日期以每个资产为准。旧 E0 / R / R1 命名及代码保持。</footer></main>
<script>const payload=__PAYLOAD__;
const Q=id=>document.getElementById(id), labels={'-2':'freeze','-1':'cold','0':'neutral','1':'warm','2':'hot'}, colors={'-2':'#37579e','-1':'#72a7bd','0':'#89877e','1':'#c78f35','2':'#cb6147'};
const phases={unknown:'预热或无效观察',acute_damage:'当前尺度内有未解除的急性量价破坏',local_decline:'月尺度已经确认下降，大背景不保护当前转弱',down_background_pause:'下降背景内，局部暂无明确恢复',no_clear_progress:'两尺度都没有明确方向证据',up_background_pause:'上行背景内整理；不等于仍在高速上涨',down_background_rebound:'局部恢复，但季尺度仍向下；不升级 hot',up_building:'局部上行正在建立，背景尚未同时确认',aligned_up:'月/季两个尺度均向上'};
const fmt=(v,d=2)=>v===null||v===undefined?'未知':Number(v).toFixed(d), sign=x=>x===null?'未知':({'-1':'下','0':'中','1':'上'}[x]);
for(const w of payload.windows){let o=document.createElement('option');o.value=w.id;o.textContent=`${w.name} · ${w.start}—${w.end} · ${w.id}`;Q('window').append(o)}
let currentWindow,indices=[];
function showWindow(id,date){Q('window').value=id;currentWindow=payload.windows.find(w=>w.id===id);let d=payload.data[currentWindow.asset];indices=d.dates.map((x,i)=>x>=currentWindow.start&&x<=currentWindow.end?i:-1).filter(i=>i>=0);Q('slider').min=0;Q('slider').max=indices.length-1;Q('date').min=d.dates[indices[0]];Q('date').max=d.dates[indices.at(-1)];Q('plot').src='../figures/real/'+id+'.png';showDate(date||d.dates[indices.at(-1)])}
function showDate(date){let d=payload.data[currentWindow.asset],eligible=indices.filter(i=>d.dates[i]<=date),i=eligible.at(-1)??indices[0];Q('slider').value=indices.indexOf(i);Q('date').value=d.dates[i];Q('dateText').textContent=d.name+' · 当日收盘已知';let f=d.fields,v=k=>f[k][i],g=v('grade');Q('cards').innerHTML=[['当前温度',g===null?'未知':labels[g],phases[v('phase')]],['月 / 季方向',sign(v('local'))+' / '+sign(v('background')),'z21 '+fmt(v('z_21'))+' · z63 '+fmt(v('z_63'))],['日冲击 q',fmt(v('shock')),'参与调整 '+fmt(v('effective_shock'))+' · 相对量 '+fmt(v('activity'))],['E0 结构',v('e0_target')===null?'未知':v('e0_target')===1?'有效':'无效','独立保留，不代表账户持仓']].map((x,j)=>`<div class="card"><div>${x[0]}</div><div class="value" style="color:${j===0?colors[g]||'#333':'inherit'}">${x[1]}</div><div class="sub">${x[2]}</div></div>`).join('');
Q('reason').textContent=(phases[v('phase')]||'')+'。'+(v('freeze_count')>0?`当前活跃事件 ${fmt(v('freeze_count'),0)} 条，最老 ${fmt(v('freeze_age'),0)} 观察，最高未收复锚 ${fmt(v('freeze_anchor_price'),3)}。`:'当前没有活跃 freeze 事件；这不等于过去跌幅已经收回。');
let rows=[['研究收盘',fmt(v('close'),4)],['月 / 季拟合位移（log百分点）',fmt(v('amplitude_21'))+' / '+fmt(v('amplitude_63'))],['真实21 / 63观察涨跌%',fmt(v('return_21'))+' / '+fmt(v('return_63'))],['旧 B1 / B2月推进 / B2结构保留',fmt(v('b1_strength'))+' / '+fmt(v('b2_pace_21'))+' / '+fmt(v('b2_signed_retention'))],['不考虑急性破坏的正常状态',labels[v('normal_grade')]||'未知'],['去量冲击对照温度',labels[v('price_grade')]||'未知'],['E0保护点',fmt(v('e0_floor'),4)]];Q('details').innerHTML='<table>'+rows.map(r=>'<tr><td>'+r[0]+'</td><td>'+r[1]+'</td></tr>').join('')+'</table>'}
Q('window').onchange=()=>showWindow(Q('window').value);Q('date').onchange=()=>showDate(Q('date').value);Q('slider').oninput=()=>showDate(payload.data[currentWindow.asset].dates[indices[+Q('slider').value]]);document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{let [id,date]=b.dataset.case.split('|');showWindow(id,date)});
let gs=payload.stats.filter(s=>['au_user_consolidation','au_user_decline'].includes(s.id));Q('goldStats').innerHTML='<table><tr><th>窗口</th><th>首尾涨跌</th><th>freeze</th><th>cold</th><th>neutral</th><th>warm</th><th>hot</th><th>温度切换</th></tr>'+gs.map(s=>'<tr><td>'+s.start+'—'+s.end+'</td><td>'+fmt(s.price_change_pct)+'%</td>'+[-2,-1,0,1,2].map(k=>'<td>'+s.counts[k]+'日</td>').join('')+'<td>'+s.changes+'次</td></tr>').join('')+'</table>';
for(const s of payload.synthetic){let o=document.createElement('option');o.value=s.id;o.textContent=s.id;Q('synthetic').append(o)}Q('synthetic').onchange=()=>Q('synthPlot').src='../figures/synthetic/'+Q('synthetic').value+'.png';Q('synthetic').value='flat_box';if(!Q('synthetic').value)Q('synthetic').selectedIndex=0;Q('synthetic').onchange();
Q('downloads').innerHTML=Object.entries(payload.data).map(([sid,d])=>`<a href="../results/${sid}.csv">${d.name}</a>`).join(' · ');showWindow('au_user_consolidation','2025-07-31');
</script></html>'''
    html=html.replace('__PAYLOAD__',json.dumps(payload,ensure_ascii=False,allow_nan=False).replace('</','<\\/'))
    (target/'index.html').write_text(html);print({'report_bytes':len(html.encode())})
if __name__=='__main__':main()
